INSERT INTO `crm_followup_categories` (`id`, `nama_kategori`, `kode_kategori`, `jumlah_hari`, `template_pesan_default`, `is_active`, `urutan`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'Konfirmasi Pengiriman', 'KONFIRMASI_KIRIM', 0, 'Halo Kak {{nama_customer}} 🙏\n\nPesanan Kakak dengan nomor {{no_pesanan}} sedang dalam proses pengiriman ya.\n\nNo. Resi: {{nomor_resi}}\nEkspedisi: {{kurir}}\nSumber: {{sumber_penjualan}}\n\nTerima kasih sudah berbelanja! 😊', 1, 1, NULL, '2026-09-01 14:49:09', NULL),
(2, 'Cek Barang Sampai', 'H_3_CEK_SAMPAI', 3, 'Halo Kak {{nama_customer}} 😊\n\nApakah pesanan Kakak ({{no_pesanan}}) sudah diterima dengan baik?\n\nProduk: {{produk}}\nDikirim tanggal: {{tanggal_kirim}}\n\nKalau sudah sampai, boleh dikonfirmasi ya Kak. Terima kasih! 🙏', 1, 2, NULL, '2026-09-01 14:49:09', '2026-09-04 13:03:42'),
(3, 'Tanya Pengalaman', 'H_7_EXPERIENCE', 7, 'Halo Kak {{nama_customer}} 😊\n\nBagaimana pengalaman menggunakan produk dari kami?\n\nProduk: {{produk}}\n\nKami sangat menghargai feedback Kakak untuk meningkatkan kualitas layanan kami. Terima kasih banyak! ⭐', 1, 3, NULL, '2026-09-01 14:49:09', '2026-09-04 13:03:42'),
(4, 'Tawarkan Repeat Order', 'REPEAT_ORDER', 30, 'Halo Kak {{nama_customer}} 👋\n\nSudah sebulan sejak pembelian terakhir Kakak. Apakah stok {{produk}} sudah mulai menipis?\n\nKami punya penawaran spesial untuk pembelian ulang lho! 🎁\n\nSilakan hubungi kami untuk info lebih lanjut ya Kak 😊', 1, 5, NULL, '2026-09-01 14:49:09', '2026-09-07 13:55:19'),
(5, 'Evaluasi Produk', 'H_11_cek', 11, 'halo kak{{nama_customer}}\nbarang sudah sampai ?\nini kurir{{kurir}}', 1, 4, 'developer', '2026-09-05 08:40:29', '2026-09-07 13:55:19');
